// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const query = input.query || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
const discordUserId = query.discord_user_id;

if (!discordUserId) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le parametre "discord_user_id" est requis'
  };
}

// --- Pagination (optionnelle) ---
const limit = Math.min(Math.max(parseInt(query.limit) || 10, 1), 50);
const offset = Math.max(parseInt(query.offset) || 0, 0);

// --- Filtre status (optionnel) ---
const status = query.status || null;

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: discordUserId,
    project_id: projectId,
    limit: limit,
    offset: offset,
    status: status
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'API_ERROR',
      message: apiResponse.error?.message || 'Erreur API',
      http_status: apiResponse.error?.http_status || 500
    }
  };
}

// --- Format orders ---
const orders = (apiResponse.orders || apiResponse.data || []).map(order => {
  const totalEuros = (order.total_cents || 0) / 100;
  const totalDisplay = totalEuros.toLocaleString('fr-FR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }) + ' EUR';

  return {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_cents: order.total_cents,
    total_display: totalDisplay,
    item_count: order.item_count || order.items?.length || 0,
    currency: order.currency || 'EUR',
    created_at: order.created_at,
    paid_at: order.paid_at
  };
});

// --- Success response ---
return {
  success: true,
  orders: orders,
  pagination: {
    total: apiResponse.total || orders.length,
    limit: validationData.data.limit,
    offset: validationData.data.offset,
    has_more: apiResponse.has_more || false
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

